import{_ as r,o as l,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2017-MAR-22 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2017-MAR-22 :: Ceph Performance Weekly","date":"2017-04-06T00:00:00.000Z","updated":"2017-04-07T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","蓝存储","OSD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-MAR-22_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2017-MAR-22_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),i={name:"posts/2017/2017-MAR-22_-_-_Ceph_Performance_Weekly.md"};function a(s,e,n,g,_,p){return l(),t("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： 全体研发人员</p><p><strong>会议主题</strong>： 讨论Ceph分布式存储的最新进展和待办事项</p><h3 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h3><ul><li><strong>新特性与需求</strong>： <ul><li><strong>Igor的PR清理</strong>： 讨论了Ashley基于早期PR的清理工作，旨在将kV sinks red和blue store分成两部分，以提高性能。目前编译存在问题，需要进一步定义和测试。</li><li><strong>零拷贝工作</strong>： 持续进行DM和nascent messenger的零拷贝工作，预计将有更多相关工作。</li><li><strong>PG重映射</strong>： Sage提出的PG重映射功能，允许用户在PG已映射后重新映射，以优化分布。这是一个长期需求的解决方案。</li><li><strong>SSD对齐</strong>： 调整SSD对齐设置，以减少内存和数据库压力。</li><li><strong>固定延迟权限</strong>： 合并了固定延迟权限的修复，可能改善性能并解决一系列问题。</li><li><strong>RC锁定机制</strong>： 改进的RC锁定机制可能不会带来显著性能提升，已被移出热路径。</li><li><strong>LP T&amp;G工作</strong>： LP T&amp;G工作分为两部分：在BOS D中引入大量tracing和直接messenger / men&#39;s store，以分离代码并专注于找到延迟。</li><li><strong>性能改进</strong>： 讨论了如何通过改进OSD性能来提高RTW性能。</li><li><strong>Brothersoft性能</strong>： 讨论了Brothersoft性能优化，包括减少内存拷贝和动态内存分配。</li><li><strong>静态指针</strong>： 讨论了静态指针的概念，以及在OSD客户端接口中使用静态指针的潜在优势。</li><li><strong>BlueStore优化</strong>： 讨论了BlueStore中与大量对象和元数据相关的性能问题，包括压缩和锁定问题。</li><li><strong>CRC32 for PVC架构</strong>： 讨论了CRC32在PVC架构中的应用。</li><li><strong>X to be arm range Keys operator interface</strong>： Sage正在测试X to be arm range Keys operator interface。</li></ul></li><li><strong>技术讨论</strong>： <ul><li><strong>数据结构</strong>： 讨论了Brewster中使用的数据结构，包括顺序结构和动态结构，以及它们对性能的影响。</li><li><strong>编码/解码</strong>： 讨论了编码/解码的性能优化，以及如何将多个值编码/解码在单个操作中。</li><li><strong>内存分配器</strong>： 讨论了内存分配器的性能优化，以及如何减少内存碎片和锁定问题。</li></ul></li></ul><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>继续推进Igor的PR清理工作，并解决编译问题。</li><li>继续进行零拷贝工作，并关注未来更多的相关工作。</li><li>推进PG重映射功能，并解决编译问题。</li><li>调整SSD对齐设置，以减少内存和数据库压力。</li><li>合并固定延迟权限的修复，并进一步测试性能。</li><li>移除RC锁定机制的改进，并关注其他性能优化方法。</li><li>继续推进LP T&amp;G工作，并关注分离代码和找到延迟。</li><li>推进性能改进工作，特别是OSD性能优化。</li><li>推进Brothersoft性能优化，包括减少内存拷贝和动态内存分配。</li><li>探索静态指针在OSD客户端接口中的应用。</li><li>优化BlueStore性能，包括减少元数据和压缩。</li><li>探索将大型对象键分区到数据库以减少压缩的可行性。</li><li>评估CRC32在PVC架构中的应用。</li><li>测试X to be arm range Keys operator interface。</li><li>优化数据结构，以提高性能。</li><li>优化编码/解码性能，并探索将多个值编码/解码在单个操作中。</li><li>优化内存分配器，以减少内存碎片和锁定问题。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>Igor：解决PG重映射PR的编译问题。</li><li>Sage：测试X to be arm range Keys operator interface。</li><li>全体研发人员：关注并参与上述各项工作的推进。</li></ul>',10)])])}const d=r(i,[["render",a]]);export{h as __pageData,d as default};
